"use client";

import * as React from "react";
import { Check, ChevronRight, RotateCcw, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ACTION RECEIPTS: what the agent did, and the way back
 *
 *   done      a quiet line per action: what happened, where;
 *             Undo with a ring that drains while you still can,
 *             folding away when the window closes
 *   undoing   the ring blurs into a spinner; "Undo" morphs to
 *             "Undoing"
 *   undone    a strike draws itself across the line; "Undone"
 *   failed    why it failed, and Retry
 *   stacked   three or more fold into "3 actions · Undo all",
 *             which opens into the list; the counts roll
 *
 * Undo is one button from first to last: its icon slot and label
 * change, it never gets swapped for another element.
 *
 * Feed it the actions your tools performed; it keeps the timing.
 * ───────────────────────────────────────────────────────── */

export type ReceiptStatus = "done" | "undoing" | "undone" | "failed";

export interface Receipt {
  id: string;
  /** What happened, e.g. "Added “Soft launch” to Saturday". */
  title: string;
  /** Where or when, e.g. "Calendar · 9:00 am". */
  detail?: string;
  icon?: React.ReactNode;
  status?: ReceiptStatus;
  error?: string;
  /** Until when it can be undone (ms timestamp). Without it, no Undo. */
  undoUntil?: number;
}

export interface ActionReceiptsProps extends React.HTMLAttributes<HTMLDivElement> {
  actions: Receipt[];
  onUndo?: (id: string) => void | Promise<void>;
  /** Defaults to undoing each undoable action. */
  onUndoAll?: () => void | Promise<void>;
  onRetry?: (id: string) => void;
  /** Fold into a summary from this many actions (0 never folds). */
  stackFrom?: number;
  /** How long the undo window is, for the ring (ms). */
  undoWindow?: number;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const LINK = `inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="flex min-w-0 items-center whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** Re-renders when the next undo window closes, so Undo disappears on time. */
function useUndoClock(actions: Receipt[]) {
  const [now, setNow] = React.useState(() => Date.now());
  React.useEffect(() => {
    const next = actions
      .map((a) => a.undoUntil ?? 0)
      .filter((t) => t > now)
      .sort((a, b) => a - b)[0];
    if (!next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), next - now + 20);
    return () => window.clearTimeout(timer);
  }, [actions, now]);
  return now;
}

/** A ring that drains from full to empty over the time left, with CSS only. */
function DrainRing({
  until,
  window: total,
  reduced,
}: {
  until: number;
  window: number;
  reduced: boolean;
}) {
  const [start] = React.useState(() => Date.now());
  const left = Math.max(0, until - start);
  const elapsed = Math.max(0, total - left);
  const c = 2 * Math.PI * 5.5;
  return (
    <svg aria-hidden="true" viewBox="0 0 14 14" className="size-3.5 -rotate-90">
      <circle
        cx="7"
        cy="7"
        r="5.5"
        fill="none"
        strokeWidth="1.5"
        className="stroke-border"
      />
      <circle
        cx="7"
        cy="7"
        r="5.5"
        fill="none"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeDasharray={c}
        className="stroke-foreground/70"
        style={
          reduced
            ? { strokeDashoffset: c * (elapsed / total) }
            : ({
                "--ui-ring": `${c}`,
                animation: `ui-drain ${total}ms linear -${elapsed}ms forwards`,
              } as React.CSSProperties)
        }
      />
    </svg>
  );
}

function Line({
  action,
  now,
  pending,
  undoWindow,
  reduced,
  onUndo,
  onRetry,
}: {
  action: Receipt;
  now: number;
  pending: boolean;
  undoWindow: number;
  reduced: boolean;
  onUndo?: (id: string) => void;
  onRetry?: (id: string) => void;
}) {
  const status = pending ? "undoing" : (action.status ?? "done");
  const canUndo =
    status === "done" && Boolean(onUndo) && (action.undoUntil ?? 0) > now;
  const undone = status === "undone";
  const failed = status === "failed";

  // The one button's state: what it says and whether it does anything.
  const mode =
    status === "undoing"
      ? "undoing"
      : undone
        ? "undone"
        : failed && onRetry
          ? "retry"
          : canUndo
            ? "undo"
            : null;
  const [lastMode, setLastMode] = React.useState(mode);
  if (mode && mode !== lastMode) setLastMode(mode);
  const shown = mode ?? lastMode;
  const actionable = mode === "undo" || mode === "retry";
  const label = {
    undo: "Undo",
    undoing: "Undoing",
    undone: "Undone",
    retry: "Retry",
  };
  const layer = "absolute inset-0 flex items-center justify-center";

  return (
    <li className="flex min-h-10 items-center gap-2.5 py-1 animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
      <span
        aria-hidden="true"
        className={`relative flex size-6 shrink-0 items-center justify-center rounded-full transition-colors duration-300 [&_svg]:size-3.5 [&_svg]:stroke-[1.8] ${
          failed
            ? "bg-red-500/10 text-red-600 dark:text-red-400"
            : "bg-muted text-muted-foreground"
        }`}
      >
        <span className={layer} style={swap(!failed, reduced)}>
          {action.icon ?? <Check />}
        </span>
        <span className={layer} style={swap(failed, reduced)}>
          <X />
        </span>
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[13px]">
          {/* The strike draws itself across the title, left to right. */}
          <span
            className={`bg-[linear-gradient(color-mix(in_oklab,currentColor_55%,transparent),color-mix(in_oklab,currentColor_55%,transparent))] bg-no-repeat [background-position:0_58%] ${undone ? "text-muted-foreground" : "text-foreground"}`}
            style={{
              backgroundSize: undone ? "100% 1px" : "0% 1px",
              transition: reduced
                ? "none"
                : `background-size 480ms ${MORPH} 80ms, color 300ms`,
            }}
          >
            {action.title}
          </span>
        </span>
        {(failed ? action.error : action.detail) && (
          <span
            className={`block truncate text-[11.5px] transition-colors duration-300 ${failed ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
          >
            {failed ? action.error : action.detail}
          </span>
        )}
      </span>

      <span role="status" className="sr-only">
        {status === "undoing"
          ? `Undoing ${action.title}`
          : undone
            ? `Undone: ${action.title}`
            : failed
              ? `Failed: ${action.error ?? action.title}`
              : ""}
      </span>
      {shown && (
        <Reveal show={Boolean(mode)} reduced={reduced} className="shrink-0">
          <span className="block p-0.5">
            <button
              type="button"
              inert={!mode}
              aria-disabled={!actionable || undefined}
              aria-label={mode === "undo" ? `Undo: ${action.title}` : undefined}
              onClick={() =>
                mode === "undo"
                  ? onUndo?.(action.id)
                  : mode === "retry"
                    ? onRetry?.(action.id)
                    : undefined
              }
              className={`inline-flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium transition-colors ${FOCUS} ${
                actionable
                  ? "text-foreground hover:bg-accent"
                  : "cursor-default text-muted-foreground"
              }`}
            >
              <span
                aria-hidden="true"
                className="relative flex size-3.5 shrink-0 items-center justify-center"
              >
                {/* Keyed by the window, so a fresh window drains from full; paused once it has faded out. */}
                <span
                  className={`${layer} ${shown === "undo" ? "" : "[&_*]:[animation-play-state:paused]"}`}
                  style={swap(shown === "undo", reduced)}
                >
                  <DrainRing
                    key={action.undoUntil}
                    until={action.undoUntil ?? 0}
                    window={undoWindow}
                    reduced={reduced}
                  />
                </span>
                <span
                  className={layer}
                  style={swap(shown === "undoing", reduced)}
                >
                  <span
                    className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${shown === "undoing" ? "animate-spin" : ""}`}
                  />
                </span>
                <span
                  className={layer}
                  style={swap(shown === "undone" || shown === "retry", reduced)}
                >
                  <RotateCcw className="size-3" />
                </span>
              </span>
              <TextMorph>{label[shown as keyof typeof label]}</TextMorph>
            </button>
          </span>
        </Reveal>
      )}
    </li>
  );
}

export function ActionReceipts({
  actions,
  onUndo,
  onUndoAll,
  onRetry,
  stackFrom = 3,
  undoWindow = 10_000,
  className = "",
  ...props
}: ActionReceiptsProps) {
  const reduced = useReducedMotion();
  const now = useUndoClock(actions);
  const [pending, setPending] = React.useState<Set<string>>(() => new Set());
  const [open, setOpen] = React.useState(false);
  const listId = React.useId();

  const undo = async (id: string) => {
    if (!onUndo) return;
    setPending((p) => new Set(p).add(id));
    try {
      await onUndo(id);
    } finally {
      setPending((p) => {
        const next = new Set(p);
        next.delete(id);
        return next;
      });
    }
  };

  const undoable = actions.filter(
    (a) =>
      (a.status ?? "done") === "done" &&
      (a.undoUntil ?? 0) > now &&
      !pending.has(a.id),
  );
  const undoAll = async () => {
    if (onUndoAll) {
      setPending(new Set(undoable.map((a) => a.id)));
      try {
        await onUndoAll();
      } finally {
        setPending(new Set());
      }
    } else await Promise.all(undoable.map((a) => undo(a.id)));
  };

  const stacked = stackFrom > 0 && actions.length >= stackFrom;
  const failed = actions.filter((a) => a.status === "failed").length;
  const undone = actions.filter((a) => a.status === "undone").length;
  const busy = pending.size > 0;

  const lines = (
    <ul aria-label="Actions taken">
      {actions.map((a) => (
        <Line
          key={a.id}
          action={a}
          now={now}
          pending={pending.has(a.id)}
          undoWindow={undoWindow}
          reduced={reduced}
          onUndo={onUndo ? undo : undefined}
          onRetry={onRetry}
        />
      ))}
    </ul>
  );

  if (!stacked) {
    return (
      <div className={`w-full ${className}`} {...props}>
        {lines}
      </div>
    );
  }

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex min-h-10 items-center gap-2.5">
        <button
          type="button"
          aria-expanded={open}
          aria-controls={listId}
          onClick={() => setOpen((o) => !o)}
          className="cursor-pointer group flex min-w-0 flex-1 items-center gap-2.5 rounded-lg py-1 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
        >
          <span aria-hidden="true" className="flex shrink-0 items-center">
            {actions.slice(0, 3).map((a, i) => (
              <span
                key={a.id}
                className={`flex size-6 items-center justify-center rounded-full ring-2 ring-background [&_svg]:size-3.5 [&_svg]:stroke-[1.8] ${i ? "-ml-2" : ""} ${
                  a.status === "failed"
                    ? "bg-red-500/10 text-red-600 dark:text-red-400"
                    : "bg-muted text-muted-foreground"
                }`}
                style={{ zIndex: 3 - i }}
              >
                {a.status === "failed" ? <X /> : (a.icon ?? <Check />)}
              </span>
            ))}
          </span>
          {/* "4 actions · 1 failed · 2 undone": counts roll, and the extra parts open in as they apply. */}
          <span className="flex min-w-0 items-baseline truncate text-[13px] text-foreground">
            <NumberRoll value={actions.length} duration={600} />
            &nbsp;
            <TextMorph>{actions.length === 1 ? "action" : "actions"}</TextMorph>
            <Reveal show={failed > 0} reduced={reduced}>
              &nbsp;·&nbsp;
              <NumberRoll value={failed} duration={600} />
              &nbsp;failed
            </Reveal>
            <Reveal show={undone > 0} reduced={reduced}>
              &nbsp;·&nbsp;
              <NumberRoll value={undone} duration={600} />
              &nbsp;undone
            </Reveal>
          </span>
          <ChevronRight
            aria-hidden="true"
            className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 group-hover:text-foreground motion-reduce:transition-none"
            style={{
              transform: open ? "rotate(90deg)" : "none",
              transitionTimingFunction: EASE,
            }}
          />
        </button>
        {onUndo && (
          // Opens while there's more than one thing to undo; says what it's doing while it does it.
          <Reveal
            show={undoable.length > 1 || busy}
            reduced={reduced}
            className="shrink-0"
          >
            <span className="block p-0.5">
              <button
                type="button"
                inert={!(undoable.length > 1 || busy)}
                onClick={() => !busy && undoAll()}
                aria-disabled={busy || undefined}
                className={`${LINK} ${busy ? "cursor-default text-muted-foreground hover:bg-transparent" : ""}`}
              >
                <span
                  aria-hidden="true"
                  className="relative flex size-3 shrink-0 items-center justify-center"
                >
                  <span
                    className="absolute inset-0 flex items-center justify-center"
                    style={swap(!busy, reduced)}
                  >
                    <RotateCcw className="size-3" />
                  </span>
                  <span
                    className="absolute inset-0 flex items-center justify-center"
                    style={swap(busy, reduced)}
                  >
                    <span
                      className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                    />
                  </span>
                </span>
                <TextMorph>{busy ? "Undoing all" : "Undo all"}</TextMorph>
              </button>
            </span>
          </Reveal>
        )}
      </div>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="ml-3 border-l border-border pl-[18px]">{lines}</div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

